 20	async function treeHash(directory) {
 21	  if (!(await lstat(directory)).isDirectory()) throw new Error('Expected an input directory: ' + directory);
 22	  const tree = await readdir(directory, { recursive: true, withFileTypes: true });
 23	  if (tree.some(entry => !entry.isDirectory() && !entry.isFile())) throw new Error('Unexpected entry in input tree: ' + directory);
