  3	// Text can keep its accessible name even when a visually clipped ancestor hides the glyphs.
  4	async function textFits(locator, figure, { allowHidden = false } = {}) {
  5	  const bounds = await figure.boundingBox();
  6	  if (!bounds) return false;
  7	  return locator.evaluate((element, { bounds, allowHidden }) => {
  8	    const style = getComputedStyle(element);
  9	    if (allowHidden && (element.hidden || element.classList.contains('axylo-visually-hidden') ||
 10	        style.display === 'none' || style.visibility === 'hidden')) return true;
 11	    if (style.display === 'none' || style.visibility !== 'visible') return false;
 12	    const clip = { left: Math.max(bounds.x, 0), top: Math.max(bounds.y, 0),
 13	      right: Math.min(bounds.x + bounds.width, innerWidth),
 14	      bottom: Math.min(bounds.y + bounds.height, innerHeight) };
 15	    for (let node = element; node instanceof HTMLElement; node = node.parentElement) {
 16	      const css = getComputedStyle(node);
 17	      if (css.opacity === '0' || css.clipPath !== 'none') return false;
 18	      const box = node.getBoundingClientRect();
 19	      if (css.overflowX !== 'visible') {
 20	        clip.left = Math.max(clip.left, box.left + node.clientLeft);
 21	        clip.right = Math.min(clip.right, box.left + node.clientLeft + node.clientWidth);
 22	      }
 23	      if (css.overflowY !== 'visible') {
 24	        clip.top = Math.max(clip.top, box.top + node.clientTop);
 25	        clip.bottom = Math.min(clip.bottom, box.top + node.clientTop + node.clientHeight);
 26	      }
 27	    }
 28	    const range = document.createRange();
 29	    range.selectNodeContents(element);
 30	    const glyphs = [...range.getClientRects()].filter(rect => rect.width > 0 && rect.height > 0);
 31	    return glyphs.length > 0 && glyphs.every(rect => rect.left >= clip.left - 1 && rect.right <= clip.right + 1 &&
 32	      rect.top >= clip.top - 1 && rect.bottom <= clip.bottom + 1);
 33	  }, { bounds, allowHidden });
 34	}
