135	  // Like the painted-gap acceptance check, read the actual stroked SVG marks in screen coordinates.
136	  // Keep M/L commands and their order so a bridge cannot pass with only its endpoints in the right places.
137	  const vertices = await figure.locator('svg.axylo-svg .axylo-scene path[stroke-width]').evaluateAll(paths =>
