20	  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
21	  const unsigned = part => part.startsWith('+') || part.startsWith('-') ? part.slice(1) : part;
22	  const digits = part => part.length > 0 && [...part].every(char => char >= '0' && char <= '9');
23	  const [mantissa, exponent, ...extra] = value.toLowerCase().split('e');
24	  if (extra.length || (exponent !== undefined && !digits(unsigned(exponent)))) return null;
25	  const parts = unsigned(mantissa).split('.');
26	  if (parts.length > 2 || !parts.every(digits)) return null;
27	  const number = Number(value);
28	  return Number.isFinite(number) ? number : null;
