 24	export async function removeWorkspace(runDirectory) {
 25	  // Unseal only our copy so an ordinary user can remove its directories.
 26	  for (const name of sealedTrees) {
 27	    const path = join(runDirectory, 'workspace', name);
 28	    const info = await lstat(path).catch(error => {
 29	      if (error.code !== 'ENOENT') throw error;
 30	    });
