 40	  const scratch = resolve(directory);
 41	  const repo = await realpath(repository);
 42	  // Check the nearest existing ancestor before creating any directories through a symlink.
 43	  let ancestor = scratch;
 44	  while (true) {
 45	    try {
 46	      if (inside(repo, await realpath(ancestor))) throw new Error('--workdir must be outside the repository.');
 47	      break;
 48	    } catch (error) {
 49	      if (error.code !== 'ENOENT') throw error;
 50	      ancestor = resolve(ancestor, '..');
 51	    }
 52	  }
 53	  await mkdir(scratch, { recursive: true });
 54	  const runDirectory = await mkdtemp(join(await realpath(scratch), 'axylo-rehearsal-'));
 55	  const workspace = join(runDirectory, 'workspace');
 56	  const home = join(runDirectory, 'home');
 57	  const temporary = join(runDirectory, 'tmp');
 58	  const codexHome = join(home, '.codex');
 59	  const claudeConfigDir = join(home, '.claude');
 60	  const docs = join(repository, 'apps/docs/dist');
 61	  const installed = join(workspace, 'node_modules/axylo');
 62	  let loginLink;
 63	  try {
 64	    await mkdir(installed, { recursive: true });
 65	    await mkdir(temporary);
 66	    if (agent === 'claude') {
 67	      await mkdir(claudeConfigDir, { recursive: true });
 68	      if (claudeLogin) {
 69	        loginLink = join(claudeConfigDir, '.credentials.json');
 70	        await symlink(resolve(claudeLogin), loginLink);
 71	      }
 72	    } else {
 73	      await mkdir(codexHome, { recursive: true });
 74	      if (codexLogin) {
 75	        if (!(await stat(codexLogin)).isFile()) throw new Error('Codex login must be a file.');
 76	        loginLink = join(codexHome, 'auth.json');
 77	        await symlink(codexLogin, loginLink);
 78	      }
 79	    }
 80	    await cp(docs, join(workspace, 'docs'), {
 81	      recursive: true,
 82	      async filter(file) {
 83	        if ((await lstat(file)).isSymbolicLink()) return false;
 84	        const path = relative(docs, file);
 85	        // Linked public examples belong to the docs. Evidence links can point to internal source snapshots.
 86	        return !path.startsWith('source/') || path === 'source/apps' || path === 'source/apps/docs' ||
 87	          /^source\/(?:apps\/docs\/)?examples(?:\/|$)/.test(path);
 88	      },
 89	    });
 90	    await exec('tar', ['-xzf', packedPackage, '--strip-components=1', '-C', installed]);
 91	    await copyFile(fixture, join(workspace, 'data.json'));
 92	    await copyFile(prompt, join(workspace, 'PROMPT.md'));
 93	    await writeFile(join(workspace, 'package.json'), '{"type":"module"}\n');
 94	    const hashes = await inputHashes?.(workspace);
 95	    await exec('chmod', ['-R', 'a-w', ...sealedTrees.map(name => join(workspace, name))]);
 96	    await exec('chmod', ['a-w', ...['data.json', 'PROMPT.md', 'package.json'].map(name => join(workspace, name))]);
 97	    return { workspace, runDirectory, home, codexHome, claudeConfigDir, temporary, loginLink, hashes };
 98	  } catch (error) {
