/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { taskFiles, readJson, tasks } from './rehearsal/files.mjs';
import { compareRows } from './rehearsal/table.mjs';
import { cells, effort, models, protocol, summarize, target, timeoutMs } from './rehearsal/protocol.mjs';

assert.deepEqual(tasks, ['daily-visits', 'regional-sales', 'signups', 'daily-revenue']);
assert.deepEqual(models, { codex: 'gpt-6.2-sol', claude: 'claude-opus-5-5' });
assert.equal(cells.length, 8);
assert.equal(target, 3);
assert.equal(effort, 'xhigh');
assert.equal(timeoutMs, 20 * 60 * 1000);
for (const task of tasks) {
  const paths = taskFiles(task);
  assert.equal(Object.hasOwn(paths, 'grammar'), task === 'daily-revenue');
  assert.equal(Object.hasOwn(paths, 'grammarExpected'), task === 'daily-revenue');
}
console.log('PASS: existing tasks, models and daily-revenue-only registration');

const testSource = await readFile('./rehearsal/test/grade.browser.test.mjs', 'utf8');
const template = testSource.match(/const revenue = "'`(['"\\s\\S]*?)"'`;/)[1];
const source = Function('"'return "'`'"' + template + '"'`;'"')();
const transform = Function('data', source.slice(source.indexOf('  const decimal'), source.indexOf('  return line')) + '\\nreturn rows;');
const paths = taskFiles('daily-revenue');
const format = new Intl.NumberFormat('en-US');
for (const [name, dataPath, expectedPath] of [
  ['primary', paths.fixture, paths.expected],
  ['alternate', paths.alternate, paths.alternateExpected],
]) {
  const [data, expected] = await Promise.all([readJson(dataPath), readJson(expectedPath)]);
  const converted = transform(data);
  assert.deepEqual(converted, data.map(row => ({ ...row, revenue: Number(row.revenue) })));
  const displayed = converted.toSorted((a, b) => a.day.localeCompare(b.day)).map(row => [row.day.slice(0, 10), format.format(row.revenue)]);
  assert.equal(compareRows(expected, displayed).pass, true);
  assert.equal(expected.valuesNotShown ?? 0, 0);
  const filtered = displayed.filter(row => row[0] "'!== '"'2026-05-05');
  assert.equal(compareRows(expected, filtered).pass, false);
  console.log('PASS: ' + name + ' conversions, rows and valid-row rejection preserved');
}

const [grammar, expected] = await Promise.all([readJson(paths.grammar), readJson(paths.grammarExpected)]);
const converted = new Map(transform(grammar).map(row => [row.day.slice(0, 10), row.revenue]));
assert.equal(converted.get('2026-05-02'), 2);
assert.equal(converted.get('2026-05-05'), '.5');
assert.equal(converted.get('2026-05-06'), '0x10');
assert.deepEqual(expected.rows.find(row => row[0] === '2026-05-02'), ['2026-05-02', 2]);
for (const day of ['2026-05-04', '2026-05-05', '2026-05-06']) assert.deepEqual(expected.rows.find(row => row[0] === day), [day, null]);
assert.equal(expected.valuesNotShown, 2);
const displayed = expected.rows.map(([day, value]) => [day, value === null ? 'No data' : format.format(value)]);
assert.equal(compareRows(expected, displayed).pass, true);
for (const [label, day, wrongValue] of [['reject +2', '2026-05-02', 'No data'], ['accept .5', '2026-05-05', '0.5'], ['accept 0x10', '2026-05-06', '16']]) {
  const wrong = displayed.map(row => row[0] === day ? [day, wrongValue] : row);
  assert.equal(compareRows(expected, wrong).pass, false);
  console.log('PASS: table comparator independently rejects ' + label);
}

function records(passes) {
  return cells.flatMap(cell => [1, 2, 3].map(slot => ({
    ...cell, protocol, slot, status: slot <= passes ? 'pass' : 'fail', timeoutMs,
    requested: { model: models[cell.agent], effort },
    observed: { model: models[cell.agent], models: [models[cell.agent]], effort },
    hashes: { docs: 'docs', grader: 'grader', package: 'package' },
    cli: { version: cell.agent }, browserVersion: 'fixture Chrome',
  })));
}
assert.equal(summarize(records(2)).pass, true);
assert.equal(summarize(records(1)).pass, false);
assert.equal(summarize(records(3).filter(record => record.slot "'!== 3)).pass, false);
assert.equal(summarize([]).pass, false);
console.log('"'PASS: two-of-three rule across all eight cells');
console.log('Read-only assertions: all passed; no browser or file-writing harness invoked.');
NODE"

